profiles.multi-node:
resources:
  # More namespaces and Builds to watch.
  requests: {cpu: 20m, memory: 64Mi}
  limits: {memory: 512Mi}

profiles.single-node:
prometheus:
  # Metrics on the pod port; no Prometheus operator assumed.
  enabled: true
  servicemonitor:
    enabled: false
# Idles at 20-40Mi; small requests fit a 2 GB node.
resources:
  requests: {cpu: 10m, memory: 32Mi}
  limits: {memory: 128Mi}
webhook:
  # Same sizing as the controller.
  resources:
    requests: {cpu: 10m, memory: 24Mi}
    limits: {memory: 64Mi}
cainjector:
  # Caches watched Secrets; the limit bounds it.
  resources:
    requests: {cpu: 10m, memory: 32Mi}
    limits: {memory: 128Mi}
startupapicheck:
  # Short-lived post-install Job.
  resources:
    requests: {cpu: 10m, memory: 16Mi}
    limits: {memory: 64Mi}

smoke.manifest:
apiVersion: cert-manager.io/v1
kind: Issuer
metadata: {name: smoke, namespace: catalog-smoke}
spec: {selfSigned: {}}
---
apiVersion: cert-manager.io/v1
kind: Certificate
metadata: {name: smoke, namespace: catalog-smoke}
spec:
  secretName: smoke-tls
  dnsNames: [smoke.example.test]
  issuerRef: {kind: Issuer, name: smoke}

profiles.single-node:
reloader:
  deployment:
    resources:
      # Caches every ConfigMap and Secret; grows with their count.
      requests: {cpu: 10m, memory: 64Mi}
      limits: {memory: 256Mi}

smoke.manifest:
apiVersion: v1
kind: ConfigMap
metadata: {name: smoke, namespace: catalog-smoke}
data: {revision: "2"}

profiles.multi-node:
# Leader election keeps one active; the webhook stays up during drains.
replicaCount: 2
resources:
  # More Clusters to watch.
  requests: {cpu: 20m, memory: 128Mi}
  limits: {memory: 512Mi}

profiles.single-node:
resources:
  # Idles near 25Mi; grows with Clusters. Chart sets none.
  requests: {cpu: 10m, memory: 64Mi}
  limits: {memory: 256Mi}

profiles.multi-node:
resources:
  # Same work; more Clusters to serve.
  requests: {cpu: 10m, memory: 64Mi}
  limits: {memory: 256Mi}

profiles.single-node:
resources:
  # Idles near 15Mi; backups run in the instance sidecar, not here.
  requests: {cpu: 10m, memory: 32Mi}
  limits: {memory: 128Mi}

smoke.manifest:
apiVersion: postgresql.cnpg.io/v1
kind: Cluster
metadata: {name: smoke, namespace: catalog-smoke}
spec:
  instances: 1
  storage: {size: 1Gi}

profiles.single-node:
manager:
  resources:
    # The chart sets none; grows with Dragonfly objects.
    requests: {cpu: 10m, memory: 64Mi}
    limits: {memory: 256Mi}
rbacProxy:
  resources:
    # Guards the metrics port; the chart asks for 64Mi.
    requests: {cpu: 5m, memory: 32Mi}
    limits: {memory: 128Mi}

resources:
  # The chart sets none; grows with MariaDB objects.
  requests: {cpu: 10m, memory: 64Mi}
  limits: {memory: 256Mi}
webhook:
  resources:
    # Only admits MariaDB objects.
    requests: {cpu: 10m, memory: 32Mi}
    limits: {memory: 128Mi}

profiles.multi-node:
# The chart's default, stated: leader election keeps one active.
replicaCount: 2
resources:
  # More MySQLClusters to reconcile.
  requests: {cpu: 20m, memory: 128Mi}
  limits: {memory: 512Mi}

profiles.single-node:
# One node: a second replica gains nothing.
replicaCount: 1
resources:
  # The chart asks for 100m and 20Mi; grows with MySQLClusters.
  requests: {cpu: 10m, memory: 64Mi}
  limits: {memory: 256Mi}

profiles.multi-node:
# Leader election keeps one active; survives a drain.
replicaCount: 2
resources:
  # More clusters to reconcile.
  requests: {cpu: 20m, memory: 128Mi}
  limits: {memory: 512Mi}

profiles.single-node:
resources:
  # Idles near 25Mi; grows with clusters. Chart sets none.
  requests: {cpu: 10m, memory: 64Mi}
  limits: {memory: 256Mi}

profiles.multi-node:
operator:
  # Leader-elected standby survives node drains.
  replicaCount: 2
resources:
  # Room for a few hundred ScaledObjects.
  operator:
    requests: {cpu: 50m, memory: 128Mi}
    limits: {memory: 512Mi}
  metricServer:
    requests: {cpu: 50m, memory: 96Mi}
    limits: {memory: 512Mi}
  webhooks:
    requests: {cpu: 20m, memory: 48Mi}
    limits: {memory: 256Mi}

profiles.single-node:
resources:
  # Chart defaults (100Mi/1000Mi) far exceed idle use.
  operator:
    requests: {cpu: 20m, memory: 64Mi}
    limits: {memory: 256Mi}
  metricServer:
    requests: {cpu: 20m, memory: 48Mi}
    limits: {memory: 256Mi}
  webhooks:
    requests: {cpu: 10m, memory: 32Mi}
    limits: {memory: 128Mi}

resources:
  # Caches ExternalSecrets and the Secrets it owns.
  requests: {cpu: 10m, memory: 64Mi}
  limits: {cpu: 200m, memory: 256Mi}
webhook:
  # Validates CRD writes only.
  resources:
    requests: {cpu: 10m, memory: 32Mi}
    limits: {cpu: 100m, memory: 128Mi}

profiles.multi-node:
resources:
  # More workloads to track. Still one replica (the chart fixes it):
  # Keel has no leader election, and two would roll each workload twice.
  requests: {cpu: 20m, memory: 64Mi}
  limits: {memory: 256Mi}

profiles.single-node:
resources:
  # Caches annotated workloads only.
  requests: {cpu: 10m, memory: 32Mi}
  limits: {memory: 128Mi}

profiles.multi-node:
agent:
  resources:
    # One agent per node; busier logs than single-node.
    requests: {cpu: 50m, memory: 64Mi}
    limits: {memory: 256Mi}
lapi:
  resources:
    # Headroom for more agents and decisions.
    requests: {cpu: 50m, memory: 96Mi}
    limits: {memory: 384Mi}

profiles.single-node:
agent:
  resources:
    # Chart asks 250Mi; an idle agent uses under 100Mi.
    requests: {cpu: 20m, memory: 48Mi}
    limits: {memory: 192Mi}
lapi:
  resources:
    # Chart asks 500Mi; LAPI on SQLite idles far below.
    requests: {cpu: 20m, memory: 64Mi}
    limits: {memory: 256Mi}

resources:
  # The chart's 200Mi request is sized for 100+ nodes.
  requests: {cpu: 20m, memory: 48Mi}
  limits: {memory: 128Mi}

profiles.multi-node:
# Leader election keeps one active; survives a drain.
replicaCount: 2
resources:
  # More clusters and buckets to reconcile.
  requests: {cpu: 20m, memory: 128Mi}
  limits: {memory: 512Mi}

profiles.single-node:
resources:
  # The chart asks for 100m and 50Mi; it idles lower.
  requests: {cpu: 10m, memory: 64Mi}
  limits: {memory: 256Mi}

resources:
  # The operator idles near 40Mi.
  requests: {cpu: 10m, memory: 48Mi}
  limits: {memory: 256Mi}

profiles.multi-node:
operatorConfig:
  resources:
    # More Services and Ingresses to reconcile.
    requests: {cpu: 50m, memory: 128Mi}
    limits: {memory: 512Mi}

profiles.single-node:
operatorConfig:
  resources:
    # Chart sets none; one controller and one tailnet node.
    requests: {cpu: 20m, memory: 64Mi}
    limits: {memory: 256Mi}

profiles.multi-node:
resources:
  # Busier nodes mean more syscalls to evaluate.
  requests: {cpu: 100m, memory: 256Mi}
  limits: {memory: 1Gi}

profiles.single-node:
resources:
  # The chart asks 512Mi; one node idles well below that.
  requests: {cpu: 50m, memory: 128Mi}
  limits: {memory: 768Mi}

profiles.multi-node:
# Two replicas, so a failure means the target is down.
replicas: 2
resources:
  # More probes per interval.
  requests: {cpu: 20m, memory: 32Mi}
  limits: {memory: 128Mi}

profiles.single-node:
resources:
  # Idles around 15Mi.
  requests: {cpu: 10m, memory: 16Mi}
  limits: {memory: 64Mi}

profiles.multi-node:
# Keeps schedules firing through node drains.
replicaCount: 2
resources:
  # More schedules on bigger clusters.
  requests: {cpu: 20m, memory: 64Mi}
  limits: {memory: 512Mi}

resources:
  # Bigger clusters, bigger backup item lists.
  requests: {cpu: 50m, memory: 128Mi}
  limits: {memory: 1Gi}

profiles.single-node:
resources:
  # Idle between backups; chart sets none.
  requests: {cpu: 20m, memory: 64Mi}
  limits: {memory: 512Mi}
